class Solution {
  public int movesToMakeZigzag(int[] nums) {
    return Math.min(cost(nums, 0), cost(nums, 1));
  }

  private int cost(int[] a, int parity) {
    long moves = 0;
    for (int i = parity; i < a.length; i += 2) {
      int left = i > 0 ? a[i - 1] : Integer.MAX_VALUE;
      int right = i + 1 < a.length ? a[i + 1] : Integer.MAX_VALUE;
      moves += Math.max(0, a[i] - Math.min(left, right) + 1L);
    }
    return (int) moves;
  }
}
